//! Friendly names for the platform types generated by `roc glue`.
//!
//! The generated names follow each type's path from the platform's
//! entrypoints (`AppForHostRoutesHandlerArg0` is the handler's first
//! argument), and an anonymous tag union is named after its tags. Keep every
//! generated name in this one file. The generated file's compile-time
//! size/alignment assertions catch any drift.

use crate::abi;

/// A route's boxed handler: `Request => Response`.
pub type RocHandler = abi::AppForHostRoutesHandlerFn;
pub type RocRequest = abi::AppForHostRoutesHandlerArg0;
pub type RocKeyValue = abi::HostHttpSendArg0Headers;
pub type RocSetting =
    abi::CompressionOrConcurrencyLimitOrCorsAllowOriginsOrCorsPermissiveOrMaxBodyBytesOrPortOrResponseCacheOrServeFilesOrTimeoutMs;
pub type RocSettingView<'a> =
    abi::CompressionOrConcurrencyLimitOrCorsAllowOriginsOrCorsPermissiveOrMaxBodyBytesOrPortOrResponseCacheOrServeFilesOrTimeoutMsView<'a>;

/// `Host.http_send!` Ok payload: `{ status, headers, body }` (no effects).
/// The same shape as an `err_handler`'s `Reply`, which glue therefore gives
/// the same type.
pub type RocHttpOk = abi::HostHttpSendResultOk;

/// One element of a handler's `effects` list: `Must(action, err_handler) | Opt(action)`.
pub type RocEffect = abi::MustOrOpt;
pub type RocEffectView<'a> = abi::MustOrOptView<'a>;
/// A `Must` effect's boxed `err_handler`: `Effect.Err -> Reply`.
pub type RocErrHandler = abi::MustOrOptMustFn;
/// The write-effect action: `DbWrite | HttpSend | Log`.
pub type RocEffectAction = abi::DbWriteOrHttpSendOrLog;
pub type RocEffectActionView<'a> = abi::DbWriteOrHttpSendOrLogView<'a>;

/// The classified error passed to a `Must` effect's boxed `err_handler`.
pub type RocEffectErr = abi::BusyOrForeignKeyViolationOrHttpFailedOrOtherOrUniqueViolation;
